    description: { de: "Ein großer altägyptischer Tempelkomplex am Ostufer des Nils in der Stadt, die heute als Luxor bekannt ist.", hu: "Egy nagy ókori egyiptomi templomkomplexum a Nílus keleti partján, a mai Luxor városában.", ro: "Un mare complex de temple egiptene antice situat pe malul estic al râului Nil, în orașul cunoscut azi sub numele de Luxor.", en: "A large Ancient Egyptian temple complex located on the east bank of the Nile River in the city today known as Luxor." , es: "Un gran complejo de templos del antiguo Egipto en la orilla este del Nilo, en la ciudad que hoy se conoce como Luxor.", pt: "Um grande complexo de templos do antigo Egito na margem leste do Nilo, na cidade hoje conhecida como Luxor.", fr: "Un grand complexe de temples de l'Égypte ancienne sur la rive est du Nil, dans la ville aujourd'hui connue sous le nom de Louxor."},
