    description: { de: "Einer der am besten erhaltenen Schreine in Ägypten, dem Falkengott Horus gewidmet.", hu: "Egyiptom egyik legjobb állapotban fennmaradt szentélye, a sólyomisten, Hórusz tiszteletére.", ro: "Unul dintre cele mai bine conservate sanctuare din Egipt, dedicat zeului șoim Horus.", en: "One of the best preserved shrines in Egypt, dedicated to the falcon god Horus." , es: "Uno de los santuarios mejor conservados de Egipto, dedicado al dios halcón Horus.", pt: "Um dos santuários mais bem preservados do Egito, dedicado ao deus falcão Hórus.", fr: "L'un des sanctuaires les mieux conservés d'Égypte, dédié au dieu faucon Horus."},
